with by_dimension as (select p.channel, p.status as order_status, count(*) as rows_total, max(e.amount) as max_amount from payments e left join orders p on e.order_id = p.id group by grouping sets ((p.channel, p.status), (p.channel), ())) select channel, order_status, rows_total, max_amount, case when order_status rlike '^(RETURNED|CANCELLED)$' then 'GROUP_B' else 'CORE' end as order_status_zone from by_dimension;
